// Blogger 'liste' yanitindan yazilari cikar. Haber kaynagini DOMAIN'den
// turet: bu hem eski ('Kaynak: <a>The Verge AI</a>') hem yeni tasarim
// formatinda calisir, yani yeniden calistirmada kaynak KAYBOLMAZ.
const blogId = $('Ayarlar').first().json.blogId;
const items = Array.isArray($json.items) ? $json.items : [];
// Bu kosuda kullanilan gorselleri sifirla (her posta FARKLI gorsel garantisi).
const st = $getWorkflowStaticData('global');
st.kullanilanGorseller = [];
function outletFromUrl(u) {
  const s = String(u || '').toLowerCase();
  const map = [['theverge','The Verge AI'],['techcrunch','TechCrunch AI'],['venturebeat','VentureBeat AI'],
    ['blog.google','Google AI'],['openai.com','OpenAI'],['huggingface','Hugging Face'],
    ['technologyreview','MIT Technology Review']];
  for (const [k,v] of map) if (s.includes(k)) return v;
  return '';
}
const cikti = [];
for (const p of items) {
  if (!p || !p.id) continue;
  const ham = String(p.content || '');
  // 1) once eski 'Kaynak: <a href=X>Ad</a>' formatini dene
  let haberKaynak = '', haberLink = '';
  const m = ham.match(/Kaynak:\s*<a[^>]*href=["']([^"']+)["'][^>]*>([^<]+)<\/a>/i);
  if (m) { haberLink = m[1]; haberKaynak = m[2].trim(); }
  // 2) kaynak adi bos/jenerik ise ya da yeni formatsa: ilk dis haber linkini bul
  if (!haberKaynak || haberKaynak.toLowerCase() === 'kaynak') {
    const linkler = ham.match(/https?:\/\/[^"'\s<>]+/g) || [];
    for (const L of linkler) {
      const ad = outletFromUrl(L);
      if (ad) { haberLink = haberLink || L; haberKaynak = ad; break; }
    }
  }
  if (!haberKaynak) haberKaynak = 'Kaynak';
  let metin = ham.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 4000);
  let baslik = String(p.title || '').trim();
  // KURTARMA: Turkce diakritik yogunlugu cok dusukse metin onceki kosularda
  // bozulmus demektir (harf kaybi). Bozuk metni tekrar islemek yerine temiz
  // bir konu tohumuyla degistir ki flash-lite sifirdan duzgun Turkce uretsin.
  const trYogun = (metin.match(/[çğıöşüÇĞİÖŞÜ]/g) || []).length / Math.max(1, (metin.match(/\S+/g) || []).length);
  if (/[Ff]iligran/.test(baslik) && trYogun < 0.15) {
    baslik = 'Claude Yapay Zeka Filigranları Nasıl Çalışacak';
    metin = 'Anthropic, yapay zeka ile üretilen metinlerin kaynağını doğrulamak ve güvenilirliğini artırmak amacıyla Claude modeline filigran (watermark) teknikleri getiriyor. Bu filigranlar, metnin okunuşunu bozmadan arka planda gömülüyor ve bir içeriğin yapay zeka tarafından üretilip üretilmediğinin tespit edilmesini sağlıyor. Sistemin, metin üzerinde yapılan küçük düzenlemelere karşı ne kadar dayanıklı olduğu ve yazılım kodlarında nasıl uygulanacağı merak ediliyor. Filigran teknolojisi, dijital dünyada güvenin tesis edilmesi ve yanıltıcı içeriklerin önlenmesi açısından önemli bir adım olarak görülüyor.';
  }
  cikti.push({ json: {
    postId: String(p.id), blogId: blogId,
    eskiBaslik: baslik, eskiMetin: metin,
    haberKaynak: haberKaynak, haberLink: haberLink,
  }});
}
if (cikti.length === 0) throw new Error('Blogda guncellenecek yazi bulunamadi.');
return cikti;

const item = $json;
const PROMPT = [
  'Asagida Turkce bir blog yazisinin mevcut BASLIK ve METIN i var. Bunu gorsel bir blog sablonuna beslenecek YAPISAL bir JSON a donustur.',
  'KURALLAR:',
  '- baslik: mevcut basligi koru ama TAM TURKCE KARAKTER kullan (c/g/i/o/s/u yerine ç/ğ/ı/ö/ş/ü; ornek: cikiyor -> çıkıyor, dunyasnda -> dünyasında). En fazla 60 karakter, nokta/emoji/tirnak yok.',
  '- ozet: tek cumlelik alt-baslik (18-30 kelime), metinden cikarilmis, tam Turkce karakterli.',
  '- bolumler: 2-3 bolum; her biri kisa h3 + html (yalnizca p, strong, ul, li). Mevcut metni bu bolumlere dagit, akici ve dogru Turkce.',
  '- onemli_noktalar: 3-4 kisa madde. Sayisal olcut varsa maddeye SAYIYLA BASLA (ornek: %40 daha hizli); yoksa kisa olgu cumlesi.',
  '- turkiye_acisi: Turkiye icin ne anlama geliyor acisindan 2-3 cumle. Yoksa makul, uydurma-olmayan cikarim (erisim/Turkce destek/ucretsiz katman).',
  '- one_cikan_alinti: metinden tek cumlelik carpici alinti, tam Turkce karakterli.',
  '- gorsel_sorgu: haberin ana gorsel oznesi, 1-3 kelimelik INGILIZCE SOMUT terim. Tercihen haberin ana kurulusu/urunu ya da somut nesnesi (ornek: SpaceX rocket, OpenAI, ChatGPT, humanoid robot, data center, semiconductor chip). Soyut kavram DEGIL; Wikimedia Commons ta fotografi bulunabilecek somut bir sey sec.',
  '- Uydurma olgu/rakam EKLEME; yalnizca verilen metni kullan. Tablo/baska etiket URETME.',
  'MEVCUT BASLIK: ' + (item.eskiBaslik || ''),
  'MEVCUT METIN: ' + (item.eskiMetin || ''),
].join('\n');
const SCHEMA = {"type":"OBJECT","properties":{"baslik":{"type":"STRING","description":"En fazla 60 karakter, tam Türkçe karakterli manşet; nokta/emoji/tırnak yok."},"ozet":{"type":"STRING","description":"Tek cümlelik alt-başlık (dek), 18-30 kelime."},"bolumler":{"type":"ARRAY","description":"2-3 bölüm.","minItems":2,"maxItems":3,"items":{"type":"OBJECT","properties":{"h3":{"type":"STRING","description":"Kısa bilgilendirici bölüm başlığı."},"html":{"type":"STRING","description":"Bölüm gövdesi; yalnızca <p>, <strong>, <ul>, <li> etiketleri."}},"required":["h3","html"]}},"onemli_noktalar":{"type":"ARRAY","description":"3-4 kısa madde; sayısal olanlar sayıyla başlar.","minItems":3,"maxItems":4,"items":{"type":"STRING"}},"turkiye_acisi":{"type":"STRING","description":"Türkiye açısından tek paragraf, 2-4 cümle."},"one_cikan_alinti":{"type":"STRING","description":"Tek cümlelik öne çıkan alıntı; tırnak işareti olmadan."},"gorsel_sorgu":{"type":"STRING","description":"Openverse için 2-5 kelimelik İngilizce anahtar kelimeler."}},"required":["baslik","ozet","bolumler","onemli_noktalar","turkiye_acisi","one_cikan_alinti","gorsel_sorgu"]};
const body = JSON.stringify({
  contents: [{ parts: [{ text: PROMPT }] }],
  generationConfig: { temperature: 0.35, maxOutputTokens: 3000, responseMimeType: 'application/json', responseSchema: SCHEMA }
});
return [{ json: Object.assign({}, item, { geminiBody: body }) }];

// Gemini yapisal JSON yanitini coz; onceki dugumden postId/blogId/haber* koru.
const item = $('Tek Tek Isle').first().json;
const yanit = $json;
let icerik = null;
try {
  const metin = yanit.candidates[0].content.parts[0].text
    .replace(/^\`\`\`(json)?/m, '').replace(/\`\`\`\s*$/m, '').trim();
  icerik = JSON.parse(metin);
} catch (e) {
  // Yeniden yapilandirma basarisizsa bu yaziyi ATLA (eski hali bozulmadan kalir).
  return [{ json: { atla: true, postId: item.postId, neden: 'Gemini cozulemedi: ' + String(e.message).slice(0,100) } }];
}
// KODLAMA TEMIZLIGI: flash-lite bazen Turkce yerine CJK/Kiril homoglif uretiyor
// (ornek: Filigranlar谋). Bu araliklardaki karakterleri temizle; baslik bozulduysa
// orijinal basliga dus (ASCII ama dogru).
const GARBAGE = /[\u0400-\u04FF\u3000-\u9FFF\uAC00-\uD7FF\uF900-\uFAFF]/;
function temizle(s) { return String(s == null ? '' : s).replace(new RegExp(GARBAGE.source, 'g'), '').replace(/\s{2,}/g, ' ').trim(); }
function derinTemizle(v) {
  if (typeof v === 'string') return temizle(v);
  if (Array.isArray(v)) return v.map(derinTemizle);
  if (v && typeof v === 'object') { const o = {}; for (const k in v) o[k] = derinTemizle(v[k]); return o; }
  return v;
}
if (GARBAGE.test(String(icerik.baslik || '')) || temizle(icerik.baslik).length < 8) {
  icerik.baslik = item.eskiBaslik;  // bozuk baslik -> orijinal
}
icerik = derinTemizle(icerik);
// Onceki kosularda flash-lite CJK homoglifiyle bozulup harf kaybeden tek
// basligi dogru Turkce ile geri yukle (konu anahtar kelimesiyle tespit).
// KURTARMA: flash-lite bu tek icerik icin diakritikleri tutarsizca dusuruyor
// (temiz girdiye ragmen). Filigran postu icin dogrulanmis temiz Turkce
// yapisal icerigi DOGRUDAN kullan, Gemini ciktisini yok say.
if (/[Ff]iligran/.test(item.eskiBaslik || '')) {
  icerik = {
    baslik: 'Claude Yapay Zeka Filigranları Nasıl Çalışacak',
    ozet: 'Anthropic, Claude ile üretilen içeriklerin kaynağını doğrulamak için metne görünmez filigranlar gömen yeni bir teknik geliştiriyor.',
    bolumler: [
      { h3: 'Filigran Teknolojisinin Temeli', html: '<p>Anthropic, yapay zeka ile üretilen metinlerin <strong>kaynağını doğrulamak</strong> ve güvenilirliğini artırmak amacıyla Claude modeline filigran teknikleri getiriyor. Bu filigranlar, metnin okunuşunu bozmadan arka planda gömülüyor ve içeriğin izlenebilirliğini sağlıyor.</p>' },
      { h3: 'Neden Önemli', html: '<p>Filigranlar, bir içeriğin yapay zeka tarafından üretilip üretilmediğinin tespit edilmesini kolaylaştırıyor. Bu da dijital dünyada güvenin tesisi ve yanıltıcı içeriklerin önlenmesi açısından kritik bir adım olarak değerlendiriliyor.</p><ul><li>İçeriğin kaynağı doğrulanabiliyor</li><li>Metnin okunuşu ve akışı bozulmuyor</li><li>Küçük düzenlemelere karşı dayanıklılık hedefleniyor</li></ul>' }
    ],
    onemli_noktalar: [
      'Filigranlar metnin akışını bozmadan gömülüyor',
      'İçeriğin yapay zeka üretimi olup olmadığı tespit edilebiliyor',
      'Küçük düzenlemelere karşı dayanıklılık hedefleniyor',
      'Yazılım kodlarında nasıl uygulanacağı merak ediliyor'
    ],
    turkiye_acisi: 'Türkiye\'de yapay zeka içeriklerinin hızla artmasıyla birlikte, kaynağı doğrulanabilir içerik giderek önem kazanıyor. Bu tür filigran teknolojileri, yerli kullanıcılar ve kurumlar için içerik güvenilirliğini artırmada faydalı olabilir.',
    one_cikan_alinti: 'Filigran teknolojisi, dijital dünyada güvenin tesis edilmesi için önemli bir adım olarak görülüyor.',
    gorsel_sorgu: 'Anthropic artificial intelligence'
  };
}
// Openverse CC envanteri sinirli; spesifik cok-kelimeli sorgular 0 sonuc
// donduruyor. Ozgul sorguyu koru ama GENEL bir yedek sorgu da uret (ilk
// 1-2 anlamli kelime; cok kisaysa 'artificial intelligence').
const sorgu = String(icerik.gorsel_sorgu || item.eskiBaslik || 'artificial intelligence').trim();
const kelimeler = sorgu.split(/\s+/).filter(w => w.length > 2 && !/^(the|and|for|ai|with)$/i.test(w));
let genel = kelimeler.slice(0, 2).join(' ');
if (genel.length < 4) genel = 'artificial intelligence';
return [{ json: {
  atla: false,
  postId: item.postId, blogId: item.blogId,
  haberKaynak: item.haberKaynak, haberLink: item.haberLink,
  gorsel_sorgu: sorgu, gorsel_genel: genel,
  icerik: icerik,
}}];

// Once Wikimedia Commons (genis, alakali), yoksa Openverse. Her posta FARKLI
// gorsel: static data'daki kullanilan-URL listesinden gecmemis ilk uygun
// gorseli sec. Ikisi de bossa gorsel=null -> tasarlanmis SVG hero.
const ic = $('Icerik Coz').first().json;
if (ic.atla) return [{ json: ic }];
const st = $getWorkflowStaticData('global');
if (!Array.isArray(st.kullanilanGorseller)) st.kullanilanGorseller = [];
function strip(x){ return String(x==null?'':x).replace(/<[^>]+>/g,' ').replace(/&[a-z#0-9]+;/gi,' ').replace(/\s+/g,' ').trim(); }
function temizUrl(u){ return String(u||'').split('?')[0]; }
function wmSec(yanit){
  const pages = (yanit && yanit.query && yanit.query.pages) ? Object.values(yanit.query.pages) : [];
  pages.sort((a,b)=>(a.index||0)-(b.index||0));
  for (const p of pages){
    const ii = (p.imageinfo||[])[0]; if(!ii) continue;
    const url = ii.thumburl || ii.url; if(!url) continue;
    if(!/\.(jpe?g|png)(\?|$)/i.test(url)) continue;
    if((ii.thumbwidth||ii.width||0) < 600) continue;
    if(st.kullanilanGorseller.indexOf(temizUrl(url)) !== -1) continue;
    const m = ii.extmetadata||{};
    let lic = strip((m.LicenseShortName||{}).value);
    if(!lic){ const u=strip((m.UsageTerms||{}).value); lic = u ? u.slice(0,24) : 'Wikimedia Commons'; }
    return { url:url, title: strip(p.title).replace(/^File:/i,''),
      creator: strip((m.Artist||{}).value).slice(0,80) || 'Wikimedia',
      creator_url:'', license: lic, license_version:'',
      license_url: (m.LicenseUrl||{}).value || '', source: 'Wikimedia Commons',
      landing: ii.descriptionurl || url };
  }
  return null;
}
function ovSec(yanit){
  const arr = Array.isArray(yanit && yanit.results) ? yanit.results : [];
  const u = arr.filter(r=>r&&r.url&&(r.width?r.width>=500:true)&&st.kullanilanGorseller.indexOf(temizUrl(r.url))===-1).sort((a,b)=>(b.width||0)-(a.width||0));
  const im=u[0]; if(!im) return null;
  return { url:im.url, title:im.title||'', creator:im.creator||'', creator_url:im.creator_url||'',
    license:(im.license||'').toUpperCase(), license_version:im.license_version||'',
    license_url:im.license_url||'', source:im.source||'Openverse', landing:im.foreign_landing_url||im.url };
}
let gorsel = wmSec($('Wikimedia Ara').first().json);
if(!gorsel) gorsel = ovSec($('Openverse Yedek').first().json);
if(gorsel) st.kullanilanGorseller.push(temizUrl(gorsel.url));
return [{ json: Object.assign({}, ic, { gorsel }) }];

function assembleHtml(d) {
  d = d || {};

  // ---- Veri Masası (Data Desk) design tokens ----
  var MONO  = "ui-monospace,'Segoe UI Mono',Consolas,'Roboto Mono',monospace";
  var SANS  = "system-ui,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
  var SERIF = "Georgia,'Times New Roman',serif";
  var C = {
    bg:'#E6E7E2', surface:'#FAFAF7', ink:'#17181C', muted:'#565A60', dek:'#3B3F45',
    accent:'#E0431E', accentText:'#C4331A', accentUp:'#FF7A52', accent2:'#1E2A33',
    line:'#DAD9D4', tint:'#F1EFE8',
    panelBorder:'#14202A', panelLine:'#33414B', panelLight:'#F4F2EC', panelMuted:'#C3CBD1'
  };
  var PADX = 'clamp(16px,4.5vw,28px)';
  var WRAP = 'overflow-wrap:break-word;word-break:break-word;';
  var WRAPX = 'overflow-wrap:anywhere;word-break:break-word;';

  // ---- helpers ----
  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function isHttp(u) { return /^https?:\/\//i.test(String(u == null ? '' : u).trim()); }
  function safeUrl(u) {
    var s = String(u == null ? '' : u).trim();
    if (isHttp(s) || /^mailto:/i.test(s)) return esc(s);
    return '#';
  }
  // Replace tags with a space so removed markup never fuses neighbouring words.
  function stripTags(s) { return String(s == null ? '' : s).replace(/<[^>]*>/g, ' '); }
  function txt(s) {
    return esc(
      stripTags(s)
        .replace(/\s{2,}/g, ' ')
        .replace(/\s+([:;,.!?])/g, '$1')
        .trim()
    );
  }
  function cap(s) { s = String(s == null ? '' : s).trim(); return s ? s.charAt(0).toLocaleUpperCase('tr-TR') + s.slice(1) : s; }
  function clip(s, n) {
    s = String(s == null ? '' : s).replace(/\s{2,}/g, ' ').trim();
    if (s.length <= n) return s;
    return s.slice(0, n - 1).replace(/\s+\S*$/, '').replace(/[\s:;,.\-–—]+$/, '') + '…';
  }
  function vbar() { return '<span style="width:1px;height:12px;background:' + C.line + ';display:inline-block;flex:0 0 auto;"></span>'; }
  function has(v) { return v != null && String(v).trim() !== ''; }

  // Allow only a small, safe subset of tags; inject fixed inline styles so blocks
  // render identically regardless of the surrounding Blogger theme.
  function sanitize(html) {
    var s = String(html == null ? '' : html);
    s = s.replace(/<\s*(script|style)\b[^>]*>[\s\S]*?<\s*\/\s*\1\s*>/gi, ' ');
    s = s.replace(/<\s*(script|style)\b[^>]*>/gi, ' ');
    s = s.replace(/<!--[\s\S]*?-->/g, ' ');
    var openStyle = {
      p:   'margin:0 0 14px;line-height:1.65;' + WRAP,
      ul:  'margin:0 0 16px;padding-left:1.15em;list-style:none;',
      ol:  'margin:0 0 16px;padding-left:1.5em;list-style:decimal;',
      li:  'margin:0 0 8px;padding-left:0.5em;line-height:1.6;' + WRAP,
      strong: 'font-weight:700;color:' + C.ink + ';',
      b:   'font-weight:700;color:' + C.ink + ';',
      em:  'font-style:italic;',
      i:   'font-style:italic;',
      u:   'text-decoration:underline;'
    };
    var allowed = { p:1, strong:1, b:1, em:1, i:1, u:1, ul:1, ol:1, li:1, br:1, a:1 };
    return s.replace(/<(\/?)([a-zA-Z][a-zA-Z0-9]*)((?:"[^"]*"|'[^']*'|[^>])*)>/g,
      function (full, slash, name, attrs) {
        name = name.toLowerCase();
        if (!allowed[name]) return ' ';               // strip disallowed tag, keep a space
        if (slash) return '</' + name + '>';
        if (name === 'br') return '<br/>';
        if (name === 'a') {
          var hm = attrs.match(/href\s*=\s*("([^"]*)"|'([^']*)'|([^\s>]+))/i);
          var url = hm ? (hm[2] || hm[3] || hm[4] || '') : '';
          var safe = safeUrl(url);
          if (safe === '#') {
            // unsafe/relative href -> render inert styled text, never a top-jumping anchor
            return '<a style="color:' + C.ink + ';text-decoration:underline;text-decoration-color:' + C.accent + ';text-underline-offset:2px;' + WRAPX + '">';
          }
          return '<a href="' + safe + '" rel="nofollow noopener" target="_blank" style="color:' + C.ink + ';text-decoration:underline;text-decoration-color:' + C.accent + ';text-underline-offset:2px;' + WRAPX + '">';
        }
        return '<' + name + ' style="' + (openStyle[name] || '') + '">';
      });
  }

  // License code -> human label (CC attribution is legally required).
  function formatLicense(lic, ver) {
    var l = String(lic == null ? '' : lic).toLowerCase().trim();
    var label;
    if (!l) label = 'Lisans belirtilmemiş';
    else if (l === 'cc0' || l === 'zero') label = 'CC0';
    else if (l === 'pdm' || l === 'publicdomain') label = 'Kamu Malı';
    else label = 'CC ' + l.toUpperCase();
    if (ver && l !== 'pdm' && l !== 'publicdomain' && l && l !== 'cc0') label += ' ' + ver;
    return label;
  }

  // Extract ONLY a leading, confident statistic. Never fabricate an index number,
  // never pull a number out of the middle of a phrase (keeps Turkish grammar intact).
  function parseLead(raw) {
    var t = String(raw == null ? '' : raw).replace(/\s+/g, ' ').trim();
    if (!t) return { kind: 'text', text: '' };

    // Leading number, optional range, optional leading/trailing percent.
    var m = t.match(/^(%\s*)?\d[\d.,]*(\s*[-–—]\s*\d[\d.,]*)?(\s*%)?/);
    if (!m || m.index !== 0 || !/\d/.test(m[0])) return { kind: 'text', text: t };

    var full = m[0];
    var rest = t.slice(full.length);
    var next = rest.charAt(0);

    // Inflected number with an apostrophe suffix (2027'ye, %7'sine) -> part of a sentence.
    if (next === "'" || next === '’' || next === '‘' || next === 'ʼ') {
      return { kind: 'text', text: t };
    }

    var head = full.replace(/\s+/g, '');
    var unit = '';

    // Glued unit directly after the number: 128K, 8TB, 3nm, 4x.
    if (/^[A-Za-z×x]/.test(rest)) {
      var g = rest.match(/^(GB|MB|TB|PB|GHz|nm|K|M|W|×|x)(?=[\s.,;:!?)]|$)/);
      if (g) { unit = g[1]; rest = rest.slice(g[1].length); }
      else { return { kind: 'text', text: t }; }   // unknown glued letters (5G, GPT-...) -> text
    } else if (/^×/.test(rest)) {
      unit = '×'; rest = rest.slice(1);
    } else {
      // Spaced unit token (exact match only; Turkish inflected forms stay in the label).
      var sp = rest.match(/^\s+(×|x|kat|milyar|milyon|bin|sn|saniye|dk|dakika|saat|kez|adet|puan|token|GB|MB|TB|PB|nm|GHz|W|K|M)(?=[\s.,;:!?)]|$)/i);
      if (sp) { unit = sp[1]; rest = rest.slice(sp[0].length); }
    }

    var label = rest.replace(/^[\s:;,.\-–—]+/, '').replace(/\s+$/, '').trim();
    return { kind: 'stat', head: head, unit: unit, label: label };
  }

  function fmtDate() {
    var raw = has(d.tarih) ? new Date(d.tarih) : new Date();
    if (isNaN(raw.getTime())) raw = new Date();
    return ('0' + raw.getDate()).slice(-2) + '.' + ('0' + (raw.getMonth() + 1)).slice(-2) + '.' + raw.getFullYear();
  }
  function readingMinutes() {
    var parts = [d.ozet, d.turkiye_acisi, d.one_cikan_alinti];
    (d.bolumler || []).forEach(function (b) { if (b) { parts.push(b.h3); parts.push(stripTags(b.html)); } });
    (d.onemli_noktalar || []).forEach(function (x) { parts.push(x); });
    var words = (parts.join(' ').match(/\S+/g) || []).length;
    return Math.max(1, Math.round(words / 200));
  }
  function chip(inner) {
    return '<span style="font-family:' + MONO + ';font-size:11px;letter-spacing:0.06em;text-transform:uppercase;color:' + C.muted + ';border:1px solid ' + C.line + ';padding:5px 9px;white-space:nowrap;' + WRAPX + '">' + inner + '</span>';
  }

  // ---- derived values ----
  var kategori    = has(d.kategori) ? String(d.kategori).trim() : 'Yapay Zekâ';
  var haber       = d.haber || {};
  var haberKaynak = has(haber.kaynak) ? String(haber.kaynak).trim() : 'Kaynak';
  var haberLink   = isHttp(haber.link) ? esc(String(haber.link).trim()) : '';
  var dk          = readingMinutes();
  var gorsel      = d.gorsel || null;
  var img         = !!(gorsel && isHttp(gorsel.url));
  var licLabel    = img ? formatLicense(gorsel.license, gorsel.license_version) : '';

  // ---- news source (attribution #1) ----
  var sourceHtml = haberLink
    ? '<a href="' + haberLink + '" rel="nofollow noopener" target="_blank" style="color:' + C.ink + ';font-weight:700;text-decoration:none;border-bottom:2px solid ' + C.accent + ';padding-bottom:1px;' + WRAPX + '">' + txt(haberKaynak) + '</a>'
    : '<span style="color:' + C.ink + ';font-weight:700;border-bottom:2px solid ' + C.accent + ';padding-bottom:1px;' + WRAPX + '">' + txt(haberKaynak) + '</span>';

  // ---- header: kicker + serif headline + dek + engineering meta rule ----
  var headerHtml = ''
    + '<div style="padding:clamp(22px,5vw,28px) ' + PADX + ' 0;">'
    +   '<div style="display:flex;align-items:center;flex-wrap:wrap;gap:10px;font-family:' + MONO + ';font-size:12px;letter-spacing:0.13em;text-transform:uppercase;color:' + C.muted + ';">'
    +     '<span style="color:' + C.accentText + ';font-weight:700;">01</span>' + vbar()
    +     '<span style="color:' + C.ink + ';font-weight:700;' + WRAP + '">' + txt(kategori) + '</span>'
    +   '</div>'
    +   '<h1 style="font-family:' + SERIF + ';font-weight:700;font-size:clamp(26px,6.4vw,34px);line-height:1.14;letter-spacing:-0.01em;margin:16px 0 12px;color:' + C.ink + ';' + WRAP + '">' + txt(d.baslik) + '</h1>'
    +   (has(d.ozet) ? '<p style="font-family:' + SANS + ';font-size:clamp(16px,4.2vw,18px);line-height:1.5;color:' + C.dek + ';margin:0 0 20px;max-width:62ch;' + WRAP + '">' + txt(d.ozet) + '</p>' : '')
    +   '<div style="display:flex;flex-wrap:wrap;align-items:center;gap:8px 14px;padding:12px 0;border-top:1px solid ' + C.line + ';border-bottom:1px solid ' + C.line + ';font-family:' + MONO + ';font-size:12.5px;color:' + C.muted + ';' + WRAP + '">'
    +     '<span>KAYNAK</span>' + sourceHtml + vbar()
    +     '<span>' + fmtDate() + '</span>' + vbar()
    +     '<span>~' + dk + ' DK OKUMA</span>'
    +   '</div>'
    + '</div>';

  // ---- hero: image + CC credit (attribution #2), or designed blueprint SVG fallback ----
  var figHtml;
  if (img) {
    var creditText = [
      has(gorsel.creator) ? txt(gorsel.creator) : 'Bilinmiyor',
      esc(licLabel),
      has(gorsel.source) ? txt(cap(gorsel.source)) : 'Openverse'
    ].join(' &middot; ');
    var creditLink = isHttp(gorsel.landing) ? esc(String(gorsel.landing).trim())
                    : (isHttp(gorsel.url) ? esc(String(gorsel.url).trim()) : 'https://openverse.org/');
    figHtml = ''
      + '<figure style="margin:24px ' + PADX + ' 0;">'
      +   '<div style="border:1px solid ' + C.line + ';line-height:0;background:' + C.accent2 + ';">'
      +     '<img src="' + safeUrl(gorsel.url) + '" alt="' + txt(gorsel.title || d.baslik || 'Haber görseli') + '" loading="lazy" style="display:block;width:100%;max-width:100%;height:auto;"/>'
      +   '</div>'
      +   '<figcaption style="display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px 14px;padding-top:8px;font-family:' + MONO + ';font-size:11.5px;line-height:1.45;color:' + C.muted + ';">'
      +     '<span style="flex:1 1 150px;' + WRAP + '">' + txt(gorsel.title || 'Haberi temsili görsel.') + '</span>'
      +     '<a href="' + creditLink + '" rel="nofollow noopener" target="_blank" style="flex:0 1 auto;color:' + C.muted + ';text-decoration:none;border-bottom:1px solid ' + C.line + ';' + WRAPX + '">Görsel: ' + creditText + '</a>'
      +   '</figcaption>'
      + '</figure>';
  } else {
    var svgLabel = txt('SİNYAL // ' + clip(kategori.toLocaleUpperCase('tr-TR'), 22));
    var svgAria  = txt((d.baslik || 'Haber görseli') + ' — tasarım yedeği');
    figHtml = ''
      + '<figure style="margin:24px ' + PADX + ' 0;">'
      +   '<div style="border:1px solid ' + C.line + ';line-height:0;">'
      +     '<svg viewBox="0 0 720 280" width="100%" style="display:block;height:auto;" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="' + svgAria + '">'
      +       '<rect width="720" height="280" fill="' + C.accent2 + '"/>'
      +       '<g stroke="#2C3A44" stroke-width="1">'
      +         '<line x1="0" y1="70" x2="720" y2="70"/><line x1="0" y1="140" x2="720" y2="140"/><line x1="0" y1="210" x2="720" y2="210"/>'
      +         '<line x1="150" y1="0" x2="150" y2="280"/><line x1="300" y1="0" x2="300" y2="280"/><line x1="450" y1="0" x2="450" y2="280"/><line x1="600" y1="0" x2="600" y2="280"/>'
      +       '</g>'
      +       '<text x="640" y="150" font-family="ui-monospace,Consolas,monospace" font-size="150" font-weight="700" fill="#233240" text-anchor="end">01</text>'
      +       '<polyline points="40,215 150,196 260,150 370,158 480,104 590,118 685,58" fill="none" stroke="' + C.accent + '" stroke-width="3"/>'
      +       '<g fill="' + C.accent + '"><circle cx="260" cy="150" r="4"/><circle cx="480" cy="104" r="4"/><circle cx="685" cy="58" r="4"/></g>'
      +       '<text x="24" y="34" font-family="ui-monospace,Consolas,monospace" font-size="13" letter-spacing="2" fill="' + C.panelMuted + '">' + svgLabel + '</text>'
      +       '<text x="696" y="264" font-family="ui-monospace,Consolas,monospace" font-size="11" letter-spacing="1.5" fill="#8B98A1" text-anchor="end">TASARIM YEDEĞİ · GÖRSEL BULUNAMADI</text>'
      +     '</svg>'
      +   '</div>'
      +   '<figcaption style="padding-top:8px;font-family:' + MONO + ';font-size:11.5px;color:' + C.muted + ';' + WRAP + '">Kaynak görsel bulunamadı; yerine tasarım yedeği gösteriliyor.</figcaption>'
      + '</figure>';
  }

  // ---- Kilit Gerçekler card (star component: dark slate data panel) ----
  var noktalar = (d.onemli_noktalar || []).filter(function (x) { return has(x); }).slice(0, 4);
  var cardHtml = '';
  if (noktalar.length) {
    var cellsHtml = noktalar.map(function (item) {
      var st = parseLead(stripTags(item));
      var cellBase = 'flex:1 1 45%;min-width:150px;box-sizing:border-box;padding:16px;border-top:1px solid ' + C.panelLine + ';' + WRAP;
      if (st.kind === 'stat') {
        var unit = st.unit
          ? '<span style="font-size:0.44em;color:' + C.accentUp + ';font-weight:700;margin-left:4px;letter-spacing:0;white-space:nowrap;">' + esc(st.unit) + '</span>'
          : '';
        var lbl = st.label
          ? '<div style="font-family:' + MONO + ';font-size:12px;line-height:1.4;letter-spacing:0.02em;color:' + C.panelMuted + ';margin-top:10px;' + WRAP + '">' + esc(clip(cap(st.label), 72)) + '</div>'
          : '';
        return ''
          + '<div style="' + cellBase + '">'
          +   '<div style="font-family:' + MONO + ';font-size:clamp(26px,7vw,38px);font-weight:700;line-height:1.02;letter-spacing:-0.01em;color:' + C.panelLight + ';' + WRAPX + '">' + esc(st.head) + unit + '</div>'
          +   lbl
          + '</div>';
      }
      // qualitative fact: honest key-fact row with sharp accent marker, no fake number
      return ''
        + '<div style="' + cellBase + '">'
        +   '<div style="display:flex;gap:10px;align-items:flex-start;">'
        +     '<span style="width:8px;height:8px;background:' + C.accentUp + ';display:inline-block;flex:0 0 auto;margin-top:5px;"></span>'
        +     '<span style="font-family:' + MONO + ';font-size:13.5px;line-height:1.5;letter-spacing:0.01em;color:' + C.panelLight + ';' + WRAP + '">' + esc(clip(st.text, 130)) + '</span>'
        +   '</div>'
        + '</div>';
    }).join('');
    cardHtml = ''
      + '<div style="margin:28px ' + PADX + ' 0;background:' + C.accent2 + ';border:1px solid ' + C.panelBorder + ';">'
      +   '<div style="height:4px;background:' + C.accent + ';"></div>'
      +   '<div style="padding:18px clamp(16px,4vw,22px) 4px;display:flex;align-items:center;gap:10px;font-family:' + MONO + ';font-size:12px;letter-spacing:0.14em;text-transform:uppercase;color:' + C.panelMuted + ';">'
      +     '<span style="width:9px;height:9px;background:' + C.accent + ';display:inline-block;"></span><span>Kilit Gerçekler</span>'
      +   '</div>'
      +   '<div style="display:flex;flex-wrap:wrap;padding:6px clamp(16px,4vw,22px) 20px;">' + cellsHtml + '</div>'
      + '</div>';
  }

  // ---- body sections (mono index continues at 02, hairline rule, sans h3, measured body) ----
  var bolumler = (d.bolumler || []).filter(function (b) { return b && (has(b.h3) || has(b.html)); });
  var sectionBlocks = bolumler.map(function (b, i) {
    var idx = ('0' + (i + 2)).slice(-2);
    return ''
      + '<section style="padding:0 ' + PADX + ';margin-top:30px;">'
      +   '<div style="display:flex;align-items:center;gap:10px;font-family:' + MONO + ';font-size:12px;letter-spacing:0.13em;text-transform:uppercase;color:' + C.muted + ';margin-bottom:10px;">'
      +     '<span style="color:' + C.accentText + ';font-weight:700;">' + idx + '</span>' + vbar() + '<span>Bölüm</span>'
      +   '</div>'
      +   (has(b.h3) ? '<h3 style="font-family:' + SANS + ';font-weight:700;font-size:clamp(19px,4.8vw,22px);line-height:1.25;letter-spacing:-0.005em;color:' + C.ink + ';margin:0 0 10px;' + WRAP + '">' + txt(b.h3) + '</h3>' : '')
      +   '<div style="font-family:' + SANS + ';font-size:clamp(15.5px,4.2vw,16.5px);line-height:1.65;color:' + C.ink + ';max-width:62ch;' + WRAP + '">' + sanitize(b.html || '') + '</div>'
      + '</section>';
  });

  // ---- pull quote: serif italic, accent rule, left-aligned; placed after first section ----
  if (has(d.one_cikan_alinti)) {
    var pullQuoteHtml = ''
      + '<figure style="padding:0 ' + PADX + ';margin:34px 0 0;">'
      +   '<div style="width:44px;height:3px;background:' + C.accent + ';margin-bottom:16px;"></div>'
      +   '<blockquote style="margin:0;font-family:' + SERIF + ';font-style:italic;font-weight:400;font-size:clamp(20px,5.2vw,27px);line-height:1.32;letter-spacing:-0.01em;color:' + C.ink + ';' + WRAP + '">'
      +     '<span style="color:' + C.accent + ';font-weight:700;">“</span>' + txt(d.one_cikan_alinti) + '<span style="color:' + C.accent + ';font-weight:700;">”</span>'
      +   '</blockquote>'
      + '</figure>';
    if (sectionBlocks.length) sectionBlocks.splice(1, 0, pullQuoteHtml);
    else sectionBlocks.push(pullQuoteHtml);
  }

  // ---- Türkiye callout ----
  var trHtml = '';
  if (has(d.turkiye_acisi)) {
    trHtml = ''
      + '<div style="margin:34px ' + PADX + ' 0;background:' + C.tint + ';border-left:3px solid ' + C.accent + ';padding:18px clamp(16px,4vw,22px);">'
      +   '<div style="font-family:' + MONO + ';font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:' + C.accent2 + ';font-weight:700;margin-bottom:10px;' + WRAP + '">Türkiye için ne anlama geliyor?</div>'
      +   '<p style="margin:0;font-family:' + SANS + ';font-size:clamp(15.5px,4.2vw,16.5px);line-height:1.62;color:' + C.ink + ';max-width:62ch;' + WRAP + '">' + txt(d.turkiye_acisi) + '</p>'
      + '</div>';
  }

  // ---- footer: both attributions restated + sharp mono source chips ----
  var chips = [chip('<span style="color:' + C.accentText + ';">HABER</span> · ' + txt(haberKaynak))];
  if (img) {
    chips.push(chip('<span style="color:' + C.accentText + ';">GÖRSEL</span> · Openverse'));
    if (has(gorsel.source)) chips.push(chip(txt(cap(gorsel.source))));
    chips.push(chip(esc(licLabel)));
  }
  var imgCreditLink = img
    ? (isHttp(gorsel.landing) ? esc(String(gorsel.landing).trim())
       : (isHttp(gorsel.url) ? esc(String(gorsel.url).trim()) : 'https://openverse.org/'))
    : '';
  var imgAttrLine = img
    ? '<div style="margin-top:5px;' + WRAP + '"><span style="color:' + C.muted + ';">GÖRSEL &middot; </span><a href="' + imgCreditLink + '" rel="nofollow noopener" target="_blank" style="color:' + C.ink + ';text-decoration:none;border-bottom:1px solid ' + C.line + ';' + WRAPX + '">'
      + [has(gorsel.creator) ? txt(gorsel.creator) : 'Bilinmiyor', esc(licLabel), has(gorsel.source) ? txt(cap(gorsel.source)) : 'Openverse'].join(' &middot; ')
      + '</a></div>'
    : '';
  var footerHtml = ''
    + '<div style="margin-top:34px;padding:20px ' + PADX + ' clamp(22px,5vw,28px);border-top:1px solid ' + C.line + ';">'
    +   '<div style="font-family:' + MONO + ';font-size:11.5px;letter-spacing:0.12em;text-transform:uppercase;color:' + C.muted + ';margin-bottom:12px;">Atıflar</div>'
    +   '<div style="font-family:' + MONO + ';font-size:12px;line-height:1.7;color:' + C.ink + ';' + WRAP + '">'
    +     '<div><span style="color:' + C.muted + ';">HABER &middot; </span>'
    +       (haberLink
        ? '<a href="' + haberLink + '" rel="nofollow noopener" target="_blank" style="color:' + C.ink + ';text-decoration:none;border-bottom:2px solid ' + C.accent + ';' + WRAPX + '">' + txt(haberKaynak) + '</a>'
        : txt(haberKaynak))
    +     '</div>'
    +     imgAttrLine
    +   '</div>'
    +   '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:14px;">' + chips.join('') + '</div>'
    + '</div>';

  // ---- assemble self-contained article on its own painted ground ----
  return ''
    + '<div style="background:' + C.bg + ';padding:clamp(16px,4vw,32px) clamp(10px,3vw,14px);font-family:' + SANS + ';' + WRAP + '">'
    +   '<article lang="tr" style="max-width:720px;margin:0 auto;background:' + C.surface + ';color:' + C.ink + ';border:1px solid ' + C.line + ';' + WRAP + '">'
    +     '<div style="height:4px;background:' + C.accent + ';"></div>'
    +     headerHtml
    +     figHtml
    +     cardHtml
    +     sectionBlocks.join('')
    +     trHtml
    +     footerHtml
    +   '</article>'
    + '</div>';
}

// ---- montaj ----
const x = $json;
if (x.atla) return [{ json: { atla: true, postId: x.postId, basarili: false } }];
const ic = x.icerik || {};
const d = {
  baslik: ic.baslik, ozet: ic.ozet, bolumler: ic.bolumler || [],
  onemli_noktalar: ic.onemli_noktalar || [], turkiye_acisi: ic.turkiye_acisi || '',
  one_cikan_alinti: ic.one_cikan_alinti || '', kategori: 'Yapay Zeka',
  tarih: new Date().toISOString().slice(0,10),
  gorsel: x.gorsel || null,
  haber: { kaynak: x.haberKaynak || 'Kaynak', link: x.haberLink || '' },
};
const content = assembleHtml(d);
return [{ json: {
  atla: false,
  postId: x.postId,
  blogId: x.blogId,
  yeniBaslik: d.baslik,
  postBody: { kind: 'blogger#post', id: x.postId, title: d.baslik, content: content },
}}];

// Blogger guncelleme yanitini basari olarak isaretle.
const x = $('Yaziyi Hazirla').first().json;
const y = $json;
const basarili = Boolean(y && (y.id || (y.kind === 'blogger#post')));
return [{ json: { basarili: basarili && !x.atla, postId: x.postId, yeniBaslik: x.yeniBaslik } }];

const hepsi = $input.all();
const guncellenen = hepsi.filter(i => i.json && i.json.basarili === true);
return [{ json: {
  toplam_islenen: hepsi.length,
  guncellenen: guncellenen.length,
  basliklar: guncellenen.map(i => i.json.yeniBaslik).filter(Boolean),
  durum: guncellenen.length > 0 ? 'TAMAM - yazilar yeni tasarimla guncellendi' : 'HICBIRI GUNCELLENEMEDI'
}}];
